package dev.mintychochip.databag.condition;

/**
 * Numeric player resources conditions can compare.
 */
public enum PlayerResourceType {
  /** Living entity health. */
  HEALTH,
  /** Player food level. */
  HUNGER,
  /** Player experience progress fraction. */
  EXPERIENCE,
  /** Player experience level. */
  LEVEL,
  /** Player absorption hearts. */
  ABSORPTION,
  /** Remaining air ticks. */
  AIR
}
